174: function applyMove(attacker, defender, move, done) {
175:   if(!battle||battle.finished)return
176:   if(move.type==='defend') {
177:     battle.guard[attacker]=true; battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+Math.abs(move.cost));
