189:   world.burst?.({x:attacker==='player'?2: -2,y:1.5,z:.3},phenotype(battle[attacker].genome).accentColor,15)
190:   toast(`${move.name} dealt ${damage} damage.`)
191:   if(move.buff==='evade')battle.guard[attacker]=true
192:   done()
193: }
